//! CLI coverage for the latest ingestion key and path.

#[path = "common/response_schema.rs"]
mod response_schema;
use std::{
    fs,
    path::Path,
    process::{Command, Output},
    time::{Duration, SystemTime},
};

use exposed::{domain::models::entity_ingestion::IngestionKey, outbound::ExposedDataPipeline};
use tempfile::TempDir;
use uuid::Uuid;

fn run_latest(root: &Path) -> anyhow::Result<Output> {
    fs::write(root.join(".env"), "")?;
    fs::write(root.join("config.yaml"), "data_dir: ./data\n")?;
    Ok(Command::new(env!("CARGO_BIN_EXE_exposed"))
        .current_dir(root)
        .env_remove("DATABASE_URL")
        .args(["data", "latest", "--config", "config.yaml"])
        .output()?)
}

fn stdout(output: &Output) -> serde_json::Value {
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(output.status.code(), Some(0));
    assert!(output.stderr.is_empty());
    let payload = serde_json::from_slice(&output.stdout).unwrap();
    response_schema::validate("latest", "Success JSON schema:", &payload);
    payload
}

fn create_run(data: &Path, key: &IngestionKey, seconds: u64) -> anyhow::Result<()> {
    ExposedDataPipeline::new_with_ingestion_key(&data.to_path_buf(), key.clone())?;
    fs::File::open(data.join(key.to_string()))?
        .set_modified(SystemTime::UNIX_EPOCH + Duration::from_secs(seconds))?;
    Ok(())
}

#[test]
fn reports_only_the_latest_key_and_absolute_run_path_without_a_database() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let data = tmp.path().join("data");
    let older: IngestionKey = "ffffffff-ffff-4fff-8fff-ffffffffffff".parse()?;
    let latest: IngestionKey = "00000000-0000-4000-8000-000000000001".parse()?;
    create_run(&data, &older, 10)?;
    create_run(&data, &latest, 20)?;
    fs::create_dir(data.join("not-an-ingestion-key"))?;
    fs::write(
        data.join(IngestionKey::default().to_string()),
        "not a directory",
    )?;

    let output = run_latest(tmp.path())?;
    let path = data.canonicalize()?.join(latest.to_string());

    assert_eq!(
        stdout(&output),
        serde_json::json!({"ingestion": {"ingestion_key": latest.to_string(), "path": path}})
    );
    assert_eq!(fs::read_dir(&data)?.count(), 4);
    Ok(())
}

#[test]
fn equal_timestamps_use_the_greatest_uuid_regardless_of_creation_order() -> anyhow::Result<()> {
    let lower = IngestionKey::new(Uuid::from_u128(1));
    let higher = IngestionKey::new(Uuid::from_u128(2));
    for keys in [[&lower, &higher], [&higher, &lower]] {
        let tmp = TempDir::new()?;
        let data = tmp.path().join("data");
        for key in keys {
            create_run(&data, key, 10)?;
        }

        let output = run_latest(tmp.path())?;
        let path = data.canonicalize()?.join(higher.to_string());

        assert_eq!(
            stdout(&output),
            serde_json::json!({"ingestion": {"ingestion_key": higher.to_string(), "path": path}})
        );
    }
    Ok(())
}

#[test]
fn missing_or_empty_store_has_no_runs_and_stays_unchanged() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let data = tmp.path().join("data");
    assert_eq!(
        stdout(&run_latest(tmp.path())?),
        serde_json::json!({"ingestion": null})
    );
    assert!(!data.exists());

    fs::create_dir(&data)?;
    assert_eq!(
        stdout(&run_latest(tmp.path())?),
        serde_json::json!({"ingestion": null})
    );
    assert_eq!(fs::read_dir(&data)?.count(), 0);
    Ok(())
}

#[test]
fn invalid_store_path_fails_with_a_read_error() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    fs::write(tmp.path().join("data"), "not a directory")?;

    let output = run_latest(tmp.path())?;

    assert_eq!(output.status.code(), Some(1));
    assert!(output.stdout.is_empty());
    let error: serde_json::Value = serde_json::from_slice(&output.stderr)?;
    assert_eq!(error.as_object().unwrap().len(), 1);
    assert!(
        error["error"]["message"]
            .as_str()
            .unwrap()
            .contains("unable to read pipeline data")
    );
    Ok(())
}
#[path = "common/response_schema.rs"]
mod response_schema;
use std::{
    fs,
    path::{Path, PathBuf},
    process::{Command, Output},
    time::{Duration, SystemTime},
};

use exposed::{domain::models::entity_ingestion::IngestionKey, outbound::ExposedDataPipeline};
use tempfile::TempDir;

fn run_copy(root: &Path, key: Option<&IngestionKey>) -> anyhow::Result<Output> {
    fs::write(root.join(".env"), "")?;
    fs::write(root.join("config.yaml"), "data_dir: ./data\n")?;
    let mut command = Command::new(env!("CARGO_BIN_EXE_exposed"));
    command.current_dir(root).env_remove("DATABASE_URL").args([
        "data",
        "copy-latest-raw",
        "--config",
        "config.yaml",
    ]);
    if let Some(key) = key {
        command.args(["--ingestion-key", &key.to_string()]);
    }
    Ok(command.output()?)
}

fn success(output: &Output) -> serde_json::Value {
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    let payload = serde_json::from_slice(&output.stdout).unwrap();
    response_schema::validate("copy-latest-raw", "Success JSON schema:", &payload);
    payload
}

fn create_run(root: &Path, key: &IngestionKey, seconds: u64) -> anyhow::Result<PathBuf> {
    let path = root.join("data").join(key.to_string());
    fs::create_dir_all(path.join("raw"))?;
    fs::File::open(&path)?.set_modified(SystemTime::UNIX_EPOCH + Duration::from_secs(seconds))?;
    Ok(path)
}

#[tokio::test]
async fn latest_raw_copies_nested_bytes_and_empty_directories_without_derived_stages()
-> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let older: IngestionKey = "ffffffff-ffff-4fff-8fff-ffffffffffff".parse()?;
    let source: IngestionKey = "00000000-0000-4000-8000-000000000001".parse()?;
    let destination = IngestionKey::default();
    let older_path = create_run(tmp.path(), &older, 10)?;
    fs::write(older_path.join("raw/older"), "wrong source")?;
    let source_path = create_run(tmp.path(), &source, 20)?;
    fs::create_dir_all(source_path.join("raw/members/nested/empty"))?;
    fs::create_dir_all(source_path.join("raw/declarations"))?;
    fs::write(
        source_path.join("raw/members/nested/capture"),
        [0, 255, 1, 128],
    )?;
    fs::write(source_path.join("raw/declarations/empty.parquet"), [])?;
    for stage in ["cleaned", "resolved"] {
        fs::create_dir(source_path.join(stage))?;
        fs::write(source_path.join(stage).join("derived"), "do not copy")?;
    }
    fs::File::open(&source_path)?.set_modified(SystemTime::UNIX_EPOCH + Duration::from_secs(20))?;
    let data = tmp.path().join("data");
    let published = data.join(destination.to_string());
    let (path, selected) = ExposedDataPipeline::copy_latest_raw(&data, destination)
        .await?
        .unwrap();
    assert_eq!(path, published);
    assert_eq!(selected, source);
    assert_eq!(
        fs::read(published.join("raw/members/nested/capture"))?,
        [0, 255, 1, 128]
    );
    assert!(published.join("raw/members/nested/empty").is_dir());
    assert!(fs::read(published.join("raw/declarations/empty.parquet"))?.is_empty());
    assert_eq!(fs::read_dir(&published)?.count(), 1);
    assert!(!published.join("raw/older").exists());
    assert_eq!(
        fs::read(source_path.join("raw/members/nested/capture"))?,
        [0, 255, 1, 128]
    );
    assert_eq!(fs::read_dir(data)?.count(), 3);
    Ok(())
}

#[test]
fn cli_defaults_to_a_fresh_uuid_v7_and_reports_source_destination_and_path() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let source = IngestionKey::default();
    let source_path = create_run(tmp.path(), &source, 10)?;
    fs::write(source_path.join("raw/capture"), "retained")?;
    let output = run_copy(tmp.path(), None)?;
    let text = success(&output);
    let key: IngestionKey = text["ingestion"]["ingestion_key"]
        .as_str()
        .unwrap()
        .parse()?;
    assert_ne!(key, source);
    assert_eq!(key.uuid().get_version_num(), 7);
    let path = tmp
        .path()
        .join("data")
        .canonicalize()?
        .join(key.to_string());
    assert_eq!(
        text,
        serde_json::json!({"ingestion": {"source_ingestion_key": source.to_string(), "ingestion_key": key.to_string(), "path": path}})
    );
    assert_eq!(fs::read_to_string(path.join("raw/capture"))?, "retained");
    Ok(())
}

